{"code":"import datetime
import re
from hermes_tools import terminal

def get_page(url):
    print(f"Fetching {url}...")
    result = terminal(f"curl -k -L -A 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36' {url}")
    return result['output']

urls = {
    "sfn": "https://spaceflightnow.com/launch-schedule/",
    "spacearchive": "https://www.spacearchive.info/vafbsked.htm",
    "spacex": "https://www.spacex.com/launches/",
    "sunrise": "https://api.sunrise-sunset.org/json?lat=33.6411&lng=-117.9186&formatted=1"
}

results = {}
for name, url in urls.items():
    results[name] = get_page(url)

# Get weather
weather = terminal("/usr/bin/weather -f SNA")
results['weather'] = weather['output']

print("--- RAW DATA FETCH COMPLETE ---")
# Keep output relevant for next steps
for name in results:
    if name != 'weather':
        # Print first 2000 chars of HTML to see structure
        print(f"--- {name} sample ---")
        print(results[name][:2000])
    else:
        print(f"--- {name} ---")
        print(results[name])
"}

