{"code":"import json
from hermes_tools import terminal
import re

urls = {
    "sf": "https://spaceflightnow.com/launch-schedule/",
    "nsf": "https://nasaspaceflight.com/news/artemis/"
}

data = {}
for key, url in urls.items():
    resp = terminal(f"curl -sL {url}")
    data[key] = resp['output']

def parse_sf(html):
    missions = []
    # Pattern for Spaceflight Now launch entries
    # <div class="datename"><span class="launchdate">...</span><span class="mission">...</span></div>
    # <div class="missiondata">Launch vehicle: ...</div><div class="missdescrip">...</div>

    entries = re.findall(r'<div class="datename">.*?<span class="launchdate">([^<]+)</span>.*?<span class="mission">([^<]+)</span>.*?<div class="missdescrip">([^<]+)</div>', html, re.S)

    crew_keywords = ["Artemis", "Crew-", "Axiom", "Starliner", "Polaris", "Soyuz MS", "Shenzhou", "Dragon", "HLS"]

    for date, name, desc in entries:
        name = name.strip()
        if any(kw.lower() in name.lower() or kw.lower() in desc.lower() for kw in crew_keywords):
            missions.append({
                "name": name,
                "date": date.strip(),
                "summary": desc.strip(),
                "url": "https://spaceflightnow.com/launch-schedule/"
            })
    return missions

def parse_nsf(html):
    # Looking for Artemis/Crew specific headlines
    articles = re.findall(r'<h3 class="post-mega-title">.*?<a href="([^"]+)".*?>(.*?)</a>', html, re.S)
    results = []
    for url, title in articles:
        title = re.sub(r'<[^>]+>', '', title).strip()
        if any(kw in title for kw in ["Artemis", "Orion", "Starship", "HLS", "Crew"]):
            results.append({"name": title, "url": url, "summary": "Recent news update from NASASpaceflight."})
    return results

sf_results = parse_sf(data['sf'])
nsf_results = parse_nsf(data['nsf'])

print("SF_RESULTS:", json.dumps(sf_results))
print("NSF_RESULTS:", json.dumps(nsf_results))
"}

