{"content": "     1|﻿import { promises as fs } from 'fs';
     2|import path from 'path';
     3|import { NextResponse } from 'next/server';
     4|import { getWorkspacePath, HERMES_ROOT, INTERNAL_FOLDERS_TO_SKIP } from '../../lib/paths';
     5|
     6|export async function GET(request: Request) {
     7|  const { searchParams } = new URL(request.url);
     8|  const mode = searchParams.get('mode') || 'memory';
     9|
    10|  try {
    11|    const workspacePath = getWorkspacePath();
    12|
    13|    // Recursively traverses directory structure and filters files based on the current 'mode'
    14|    // Each call returns an ARRAY of FILE/DIRECTORY objects with metadata, which are then flattened and filtered according to the mode's criteria
    15|    async function getFiles(dir: string): Promise<any[]> {
    16|      // Normalize path separators to forward slashes for consistent path comparisons
    17|      const normalDir = dir.replace(/\\/g, '/');
    18|      
    19|      // Read all entries (files and directories) in the current directory
    20|      const entries = await fs.readdir(dir, { withFileTypes: true });
    21|      
    22|      // Process each ENTRY asynchronously and collect results
    23|      const files = await Promise.all(entries.map(async (entry) => {
    24|        const fullPath = path.join(dir, entry.name);
    25|        const relativePath = path.relative(workspacePath, fullPath);
    26|
    27|        // handle DIRECTORY
    28|        if (entry.isDirectory()) {
    29|          if (INTERNAL_FOLDERS_TO_SKIP.includes(entry.name)) return null;
    30|
    31|          //console.log('Checking', mode, 'mode for directory:', entry.name, 'in', normalDir);
    32|
    33|          // Filter directories based on the current mode - only include matching directory patterns
    34|          if (mode === 'docs') {
    35|            // Don't recurse into subfolders for docs mode - only get top-level markdown files
    36|            return null;
    37|          } else if (mode === 'memory') {
    38|            // Only include 'memories' folder and its contents
    39|            if (entry.name !== 'memories' && !normalDir.includes('/memories')) return null;
    40|          } else if (mode === 'logs') {
    41|            // Only include 'logs' folder and its contents
    42|            if (entry.name !== 'logs' && !normalDir.includes('/logs')) return null;
    43|          } else if (mode === 'specs') {
    44|            // Only include 'specs' folder and its contents
    45|            if (entry.name !== 'specs' && !normalDir.includes('/specs')) return null;
    46|          }
    47|
    48|          // Recursively get FILES from this SUBDIRECTORY - this will return an array of FILE/DIRECTORY objects for the subdirectory, which we will attach as 'children' to this directory object
    49|          const children = await getFiles(fullPath);
    50|          // Skip EMPTY DIRECTORIES
    51|          if (children.length === 0) return null;
    52|
    53|          return {
    54|            name: entry.name,
    55|            type: 'directory',
    56|            path: relativePath,
    57|            children: children
    58|          };
    59|        } 
    60|
    61|        // handle FILE
    62|        else {
    63|          // Process FILE entries
    64|          const stats = await fs.stat(fullPath);
    65|          
    66|          // List of FILE EXTENSIONS that should be treated as code files
    67|          const codeExts = ['.sh', '.py', '.js', '.ts', '.tsx', '.css', '.json', '.gitignore', '.env', '.html', '.yaml', '.yml'];
    68|          // Check if this FILE has a code extension
    69|          const isCode = codeExts.some(ext => entry.name.endsWith(ext));
    70|          // Check if this is a SPEC FILE (ends with _spec.md or is in specs folder) but not code
    71|          const isSpec = (entry.name.endsWith('_spec.md') || normalDir.includes('/specs')) && !isCode;
    72|          // Check if this FILE is in the memories folder
    73|          const isMemoryFile = normalDir.includes('/memories');
    74|
    75|          // Filter FILES based on mode - only return FILES that match the mode's criteria
    76|          if (mode === 'docs') {
    77|            // Return only MARKDOWN FILES for 'docs' mode
    78|            return entry.name.endsWith('.md') ? { name: entry.name, type: 'file', path: relativePath, updatedAt: stats.mtimeMs } : null;
    79|          }
    80|
    81|          if (mode === 'memory') {
    82|            // Return only MARKDOWN FILES from 'memories' folder that aren't specs
    83|            return (isMemoryFile && entry.name.endsWith('.md') && !isSpec) ? { name: entry.name, type: 'file', path: relativePath, updatedAt: stats.mtimeMs } : null;
    84|          }
    85|
    86|          if (mode === 'logs') {
    87|            // Return only LOG FILES for 'logs' mode
    88|            return entry.name.endsWith('.log') ? { name: entry.name, type: 'file', path: relativePath, updatedAt: stats.mtimeMs } : null;
    89|          }
    90|
    91|          if (mode === 'specs') {
    92|            // Return only SPEC FILES for 'specs' mode (files that are identified as specs but not code files)
    93|            return isSpec ? { name: entry.name, type: 'file', path: relativePath, updatedAt: stats.mtimeMs } : null;
    94|          }
    95|
    96|          // If no mode matched, return null (file doesn't match any filter)
    97|          return null;
    98|        }
    99|      }));
   100|      
   101|      // Flatten the array (removes nested arrays from directory recursion) and remove null entries
   102|      return files.flat().filter(f => f !== null);
   103|    }
   104|
   105|    let fileTree = await getFiles(workspacePath);
   106|
   107|    // Mode-specific sorting and formatting
