{"code":"from hermes_tools import terminal
import re

vafb_html = terminal("curl -s -L https://www.spacearchive.info/vafbsked.htm")['output']

# Look for the date/time/mission pattern in the body
# Typical row: <TR> <TD>Date</TD> <TD>Time</TD> <TD>Mission</TD> ... </TR>
rows = re.findall(r'<TR>(.*?)</TR>', vafb_html, re.S)
schedule = []
for row in rows:
    cols = re.findall(r'<TD.*?>(.*?)</TD>', row, re.S)
    if len(cols) >= 3:
        # Clean tags
        clean_cols = [re.sub(r'<.*?>', '', c).strip() for c in cols]
        if any(year in clean_cols[0] for year in ['2026', 'May']):
             schedule.append(clean_cols)

print("VAFB Schedule Rows:")
for s in schedule:
    print(s)

# Try to find specific upcoming missions like Starlink
for line in vafb_html.splitlines():
     if 'Starlink' in line:
         print(f"Starlink line: {line.strip()}")
"}

