{"code":"from hermes_tools import terminal
import re
import datetime

def get_page(url):
    return terminal(f"curl -L -s {url}").get("output", "")

vafb_sked = get_page("https://www.spacearchive.info/vafbsked.htm")
# Let's search for "SLC-4" which is common for SpaceX at Vandenberg
slc_idx = vafb_sked.find("SLC-4")
if slc_idx != -1:
    print("--- CONTENT AROUND SLC-4 ---")
    print(vafb_sked[slc_idx-500:slc_idx+500])
else:
    print("SLC-4 not found")

# Search for "Launch Time" exactly
lt_idx = vafb_sked.find("Launch Time")
if lt_idx != -1:
    print("--- CONTENT AROUND Launch Time ---")
    print(vafb_sked[lt_idx-50:lt_idx+500])
else:
    print("Launch Time not found")

# Sun Page - let's check for the current date inside the sunrise-sunset.org source
today = datetime.date.today()
today_search = today.strftime("%B %d, %Y")
print(f"Searching for {today_search} in sun page...")
if today_search in get_page("https://sunrise-sunset.org/us/costa-mesa-ca"):
    print("Found today's date in sun page")
else:
    print("Today's date not found in sun page")
    # Try just the month and day
    today_md = today.strftime("%B %d")
    if today_md in get_page("https://sunrise-sunset.org/us/costa-mesa-ca"):
        print(f"Found {today_md} in sun page")
"}

